// JSON Cleaning + Error Handling (try-catch)
const raw = $input.first().json.text ?? $input.first().json.output ?? '';
const meta = $('Konversi Base64 + Timestamp').first().json;

let hasil;
let status = 'VALID';

try {
  // 1. Buang code fence markdown (```json ... ```)
  let cleaned = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

  // 2. Ambil hanya bagian objek JSON (dari { pertama sampai } terakhir)
  const awal = cleaned.indexOf('{');
  const akhir = cleaned.lastIndexOf('}');
  if (awal === -1 || akhir === -1) {
    throw new Error('Output AI tidak mengandung objek JSON');
  }
  cleaned = cleaned.substring(awal, akhir + 1);

  // 3. Parse
  hasil = JSON.parse(cleaned);

  // 4. Validasi field wajib
  if (!hasil.ringkasan_profil || !hasil.skill_utama || !hasil.rekomendasi) {
    throw new Error('Field ringkasan_profil / skill_utama / rekomendasi tidak lengkap');
  }
} catch (err) {
  status = 'GAGAL_PARSE: ' + err.message;
  hasil = {
    ringkasan_profil: 'Output AI tidak valid, perlu review manual oleh HRD.',
    skill_utama: [],
    rekomendasi: 'Review manual'
  };
}

const skills = Array.isArray(hasil.skill_utama)
  ? hasil.skill_utama
  : String(hasil.skill_utama).split(',').map(s => s.trim()).filter(Boolean);

const pesan_telegram =
`📄 PENGAJUAN CV BARU
━━━━━━━━━━━━━━━━━━
👤 Nama: ${meta.nama}
📧 Email: ${meta.email}
💼 Posisi: ${meta.posisi}
🕒 Waktu: ${meta.waktu_pengajuan}

📝 Ringkasan Profil:
${hasil.ringkasan_profil}

🛠 Skill Utama:
${skills.length ? skills.map(s => '• ' + s).join('\n') : '-'}

✅ Rekomendasi:
${hasil.rekomendasi}

Status parsing: ${status}`;

return [{
  json: {
    status_parsing: status,
    nama: meta.nama,
    email: meta.email,
    posisi: meta.posisi,
    waktu_pengajuan: meta.waktu_pengajuan,
    ringkasan_profil: hasil.ringkasan_profil,
    skill_utama: skills,
    rekomendasi: hasil.rekomendasi,
    pesan_telegram
  }
}];
